{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "The active diacid perindoprilat (S-9780) reached only 19% systemic availability after oral perindopril in young healthy subjects, the only sub-20% result among the ACE-inhibitor analogues; although this reflects metabolite formation from a prodrug, it aligns with the poor oral absorption expected for a dianionic active diacid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "SQ 29852, a phosphoryl-containing ACE inhibitor with a primary amine and a monoanionic/zwitterionic state, had 66% oral bioavailability in humans; this is the closest phosphinic-acid analogue, but its basic amine and different charge state substantially limit transferability to the dianionic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C32"],
      "claim": "Quinapril, an ester prodrug, has about 50% absolute oral bioavailability in humans; its high absorption depends on ester masking of acidic groups, so it is not transferable to the free diacid query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Omapatrilat, an active acid with a single carboxylate and no phosphinate, has about 30% oral bioavailability; it is above the threshold but is much less negatively charged than the query, limiting its relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fosinoprilat, a dianionic phosphinic acid ACE inhibitor with no basic center. Although several ester prodrug ACE inhibitors and a zwitterionic phosphinic acid analogue show high oral bioavailability, those results depend on masking acidic groups or on a basic amine that reduces net negative charge. The query's two acidic groups, low logD, and high TPSA predict poor passive permeability, and the only sub-20% active-di-acid result (perindoprilat, 19%) supports a low F. Therefore predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for fosinoprilat itself.",
    "The closest phosphinic acid analogue (SQ 29852) has a basic amine and different charge state, limiting transferability.",
    "Most high-bioavailability evidence comes from ester prodrugs, not the free diacid form.",
    "Active diacid data are either from metabolite formation after prodrug dosing or from less negatively charged molecules."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "low",
      "card_ids": ["C17"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "phosphinic acid ACE inhibitor"
    },
    {
      "applicability": "low",
      "card_ids": ["C32"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "ACE inhibitor prodrug"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C26"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "active diacid ACE inhibitor"
    }
  ],
  "revision_action": "initial"
}

